package it.penny.api.sales;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

/** Order headers group the stable sales ledger identities used by allocations and margins. */
@RestController
@RequestMapping("/api/sales-orders")
public class SalesOrderController {
 private final M2Support s; private final ObjectMapper json; private final it.penny.api.margins.MarginService margins;
 public SalesOrderController(M2Support s,ObjectMapper json,it.penny.api.margins.MarginService margins){this.s=s;this.json=json;this.margins=margins;}
 public record Line(Long catalogProductId,Integer quantity,BigDecimal unitPrice,ObjectNode business){}
 public record Input(Long customerId,String orderNumber,LocalDate soldOn,String notes,List<Line> lines){}
 @GetMapping public Map<String,Object> list(@RequestParam(defaultValue="") String q,@RequestParam(required=false)Long customerId,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication auth){
  s.require(auth,"SALES_READ");M2Support.pagination(page,size);if(from!=null&&to!=null&&to.isBefore(from)||status!=null&&!status.isBlank()&&!Set.of("DRAFT","CONFIRMED","CANCELLED").contains(status))throw M2Support.bad("Filtri ordine non validi");
  String where=" FROM penny_sales_orders o JOIN penny_customers c ON c.id=o.customer_id WHERE lower(o.order_number||' '||c.name) LIKE :q AND (CAST(:customer AS bigint) IS NULL OR o.customer_id=:customer) AND (CAST(:from AS date) IS NULL OR o.sold_on>=:from) AND (CAST(:to AS date) IS NULL OR o.sold_on<=:to) AND (CAST(:status AS varchar) IS NULL OR o.status=:status)";
  var named=new org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate(s.db);var params=new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("q",M2Support.like(q)).addValue("customer",customerId).addValue("from",from).addValue("to",to).addValue("status",status==null||status.isBlank()?null:status).addValue("limit",size).addValue("offset",page*size);
  return Map.of("items",named.queryForList("SELECT o.id,o.customer_id AS \"customerId\",c.name AS \"customerName\",o.order_number AS \"orderNumber\",o.sold_on AS \"soldOn\",o.status,(SELECT count(*) FROM penny_sales WHERE order_id=o.id) AS \"lineCount\",(SELECT coalesce(sum(quantity*unit_price),0)::text FROM penny_sales WHERE order_id=o.id) AS \"totalAmount\""+where+" ORDER BY o.sold_on DESC,o.id DESC LIMIT :limit OFFSET :offset",params),"total",Objects.requireNonNull(named.queryForObject("SELECT count(*)"+where,params,Long.class)),"page",page,"size",size);
 }
 @GetMapping("/{id}") public Map<String,Object> get(@PathVariable long id,Authentication auth){s.require(auth,"SALES_READ");var header=s.row("penny_sales_orders",id,false);var lines=s.db.queryForList("SELECT id,catalog_product_id AS \"catalogProductId\",product_name AS \"productName\",category,quantity,unit_price::text AS \"unitPrice\",business::text AS business,status FROM penny_sales WHERE order_id=? ORDER BY id",id);lines.forEach(l->{try{l.put("business",json.readTree((String)l.get("business")));}catch(Exception e){throw new IllegalStateException(e);}});header.put("lines",lines);return header;}
 @PostMapping @Transactional public Map<String,Object> create(@RequestBody Input input,Authentication auth){
  s.require(auth,"SALES_WRITE","CUSTOMERS_READ","CATALOG_READ");if(input==null||input.soldOn()==null||input.lines()==null||input.lines().isEmpty()||input.lines().size()>100)throw M2Support.bad("Data e da 1 a 100 righe obbligatorie");s.customer(input.customerId(),true);
  String number=M2Support.required(input.orderNumber(),200,"Numero ordine");
  long order=Objects.requireNonNull(s.db.queryForObject("INSERT INTO penny_sales_orders(customer_id,order_number,sold_on,notes) VALUES (?,?,?,?) RETURNING id",Long.class,input.customerId(),number,input.soldOn(),M2Support.clean(input.notes(),10000)));
  for(Line line:input.lines()){
   if(line==null||line.catalogProductId()==null)throw M2Support.bad("Prodotto obbligatorio");int qty=M2Support.quantity(line.quantity());BigDecimal price=line.unitPrice();if(price==null||price.signum()<0||price.stripTrailingZeros().scale()>2||price.compareTo(new BigDecimal("999999999.99"))>0)throw M2Support.bad("Prezzo non valido");
   var products=s.db.queryForList("SELECT p.*,c.operational_kind,t.name AS type_name FROM penny_catalog_products p JOIN penny_product_categories c ON c.id=p.category_id LEFT JOIN penny_product_types t ON t.id=p.product_type_id WHERE p.id=? AND p.deleted_at IS NULL AND p.active AND c.active AND NOT coalesce(t.obsolete,false) FOR SHARE OF p,c",line.catalogProductId());if(products.isEmpty())throw M2Support.bad("Prodotto non vendibile");var p=products.getFirst();ObjectNode incoming=line.business()==null?json.createObjectNode():line.business().deepCopy();if("HARDWARE".equals(p.get("operational_kind"))&&!incoming.hasNonNull("warrantyMonths")&&p.get("warranty_years") instanceof Number years)incoming.put("warrantyMonths",years.intValue()*12);ObjectNode b=validateBusiness(incoming);b.put("operationalKind",String.valueOf(p.get("operational_kind")));if(p.get("category_id") instanceof Number category)b.put("categoryId",category.longValue());if(p.get("product_type_id") instanceof Number type)b.put("productTypeId",type.longValue());if(p.get("type_name")!=null)b.put("productTypeName",p.get("type_name").toString());
   Long saleId=s.db.queryForObject("INSERT INTO penny_sales(customer_id,catalog_product_id,product_code,product_name,origin,category,sold_on,quantity,unit_price,reference,notes,order_id,business,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,'DRAFT') RETURNING id",Long.class,input.customerId(),line.catalogProductId(),p.get("code"),p.get("name"),p.get("origin"),p.get("category"),input.soldOn(),qty,price,number,input.notes(),order,b.toString());margins.snapshot(Objects.requireNonNull(saleId),auth);
  }
  s.audit(auth,"SALES_ORDER_CREATED","SALES_ORDER",order,Map.of("lineCount",input.lines().size()));return Map.of("id",order);
 }
 static ObjectNode validateBusiness(ObjectNode input){ObjectNode b=input==null?com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode():input.deepCopy();if(b.toString().length()>20000)throw M2Support.bad("Dettagli troppo lunghi");for(String k:List.of("operationType","licenseType","licenseId","serialNumber","soldRelease")){if(b.hasNonNull(k)&&(!b.get(k).isTextual()||b.get(k).asText().length()>240))throw M2Support.bad("Dettaglio non valido: "+k);}for(String k:List.of("durationMonths","warrantyMonths")){if(b.hasNonNull(k)&&(!b.get(k).isIntegralNumber()||b.get(k).asInt()<0||b.get(k).asInt()>1200))throw M2Support.bad("Durata non valida");}LocalDate start=date(b,"effectiveFrom"),end=date(b,"expiresOn");if(start!=null&&end!=null&&end.isBefore(start))throw M2Support.bad("Scadenza precedente alla decorrenza");if(start!=null&&!b.hasNonNull("expiresOn")&&b.hasNonNull("durationMonths")){b.put("expiresOn",start.plusMonths(b.get("durationMonths").asInt()).toString());b.put("expiryDerived",true);}if(start!=null&&!b.hasNonNull("warrantyExpiresOn")&&b.hasNonNull("warrantyMonths")){b.put("warrantyExpiresOn",start.plusMonths(b.get("warrantyMonths").asInt()).toString());b.put("warrantyDerived",true);}date(b,"warrantyExpiresOn");return b;}
 private static LocalDate date(ObjectNode b,String key){if(!b.hasNonNull(key))return null;try{return LocalDate.parse(b.get(key).asText());}catch(Exception e){throw M2Support.bad("Data non valida: "+key);}}
 @PostMapping("/{id}/confirm") @Transactional public Map<String,Object> confirm(@PathVariable long id,Authentication auth){
  s.require(auth,"SALES_WRITE");var order=s.row("penny_sales_orders",id,true);if("CANCELLED".equals(order.get("status")))throw M2Support.conflict("Ordine annullato");if("CONFIRMED".equals(order.get("status")))return Map.of("confirmed",true);var lines=s.db.queryForList("SELECT s.*,c.operational_kind,p.product_type_id FROM penny_sales s JOIN penny_catalog_products p ON p.id=s.catalog_product_id JOIN penny_product_categories c ON c.id=p.category_id WHERE order_id=? ORDER BY s.id FOR UPDATE OF s",id);
  for(var line:lines){s.db.update("UPDATE penny_sales SET status='CONFIRMED' WHERE id=? AND status='DRAFT'",line.get("id"));generate(line,auth);}s.db.update("UPDATE penny_sales_orders SET status='CONFIRMED',updated_at=now() WHERE id=?",id);s.audit(auth,"SALES_ORDER_CONFIRMED","SALES_ORDER",id,Map.of());return Map.of("confirmed",true);
 }
 private void generate(Map<String,Object> l,Authentication auth){
  long sale=((Number)l.get("id")).longValue();String kind=(String)l.get("operational_kind");ObjectNode b;try{b=(ObjectNode)json.readTree(l.get("business").toString());}catch(Exception e){throw new IllegalStateException(e);}b.put("saleSource","OUR_SALE");b.put("saleId",sale);b.put("orderId",((Number)l.get("order_id")).longValue());
  if(Set.of("SOFTWARE","HARDWARE").contains(kind)){
   s.require(auth,"PRODUCTS_WRITE","PRODUCTS_READ");int units=kind.equals("HARDWARE")?((Number)l.get("quantity")).intValue():1;if(units>1000)throw M2Support.bad("Confermare al massimo 1000 unità hardware per riga");
   for(int unit=1;unit<=units;unit++){int qty=kind.equals("HARDWARE")?1:((Number)l.get("quantity")).intValue();if(s.db.queryForObject("SELECT count(*) FROM penny_installed_products WHERE sale_id=? AND sale_unit=?",Integer.class,sale,unit)>0)continue;
    long resource=Objects.requireNonNull(s.db.queryForObject("INSERT INTO penny_installed_products(customer_id,category,name,origin,catalog_product_id,quantity,product_type_id,business,sale_id,sale_unit) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?) RETURNING id",Long.class,l.get("customer_id"),l.get("category"),l.get("product_name"),l.get("origin"),l.get("catalog_product_id"),qty,l.get("product_type_id"),installedBusiness(b,kind).toString(),sale,unit));s.db.update("UPDATE penny_installed_products SET license_key=?,serial_number=?,installed_on=?,license_expires_on=?,warranty_until=? WHERE id=?",kind.equals("SOFTWARE")?text(b,"licenseId"):null,kind.equals("HARDWARE")&&unit==1?text(b,"serialNumber"):null,date(b,"effectiveFrom"),kind.equals("SOFTWARE")?date(b,"expiresOn"):null,date(b,"warrantyExpiresOn"),resource);s.db.update("INSERT INTO penny_sale_allocations(sale_id,installed_product_id,customer_id,catalog_product_id,quantity) VALUES (?,?,?,?,?)",sale,resource,l.get("customer_id"),l.get("catalog_product_id"),qty);
   }
  }else if(Set.of("TRAINING","CONTRACT","DEVELOPMENT").contains(kind)){
   s.require(auth,it.penny.api.records.CustomerRecordService.permission(kind)+"_WRITE");if(s.db.queryForObject("SELECT count(*) FROM penny_customer_records WHERE sale_id=?",Integer.class,sale)>0)return;
   ObjectNode d=json.createObjectNode();if(!kind.equals("DEVELOPMENT")){d.put("soldOn",l.get("sold_on").toString());d.put("price",l.get("unit_price").toString());}if(kind.equals("CONTRACT"))d.put("contractType","GENERAL");
   s.db.update("INSERT INTO penny_customer_records(customer_id,kind,name,product_type_id,sale_id,starts_on,expires_on,status,notes,details) VALUES (?,?,?,?,?,?,?,?,?,?::jsonb)",l.get("customer_id"),kind,l.get("product_name"),l.get("product_type_id"),sale,date(b,"effectiveFrom"),date(b,"expiresOn"),kind.equals("CONTRACT")?"ACTIVE":"PLANNED",l.get("notes"),d.toString());
  }else throw M2Support.bad("Categoria senza parco prodotti supportato");
 }
 private static String text(ObjectNode b,String key){return b.hasNonNull(key)?b.get(key).asText():null;}
 private static ObjectNode installedBusiness(ObjectNode b,String kind){ObjectNode result=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("saleSource","OUR_SALE");if(kind.equals("SOFTWARE")){for(String key:List.of("licenseType","soldRelease"))if(b.hasNonNull(key))result.set(key,b.get(key));if(b.hasNonNull("operationType"))result.set("softwareSaleType",b.get("operationType"));result.put("softwareStatus",text(b,"licenseId")==null?"TO_INSTALL":"ACTIVE");}else{if(b.hasNonNull("operationType"))result.set("saleType",b.get("operationType"));if(b.hasNonNull("expiresOn"))result.set("expiresOn",b.get("expiresOn"));if(b.hasNonNull("warrantyMonths")&&b.get("warrantyMonths").asInt()%12==0)result.put("warrantyYears",b.get("warrantyMonths").asInt()/12);}return result;}
 @PutMapping("/{id}/lines/{lineId}/operations") @Transactional public Map<String,Object> operations(@PathVariable long id,@PathVariable long lineId,@RequestBody ObjectNode input,Authentication auth){s.require(auth,"SALES_WRITE");s.row("penny_sales_orders",id,true);var rows=s.db.queryForList("SELECT * FROM penny_sales WHERE id=? AND order_id=? FOR UPDATE",lineId,id);if(rows.isEmpty())throw M2Support.missing("Riga");ObjectNode previous;try{previous=(ObjectNode)json.readTree(rows.getFirst().get("business").toString());}catch(Exception ex){throw new IllegalStateException(ex);}if(input==null)throw M2Support.bad("Dettagli obbligatori");input.fieldNames().forEachRemaining(k->{if(!Set.of("licenseId","serialNumber","effectiveFrom","expiresOn","warrantyExpiresOn","soldRelease").contains(k))throw M2Support.bad("Campo operativo non modificabile: "+k);});if(input.has("effectiveFrom")){if(previous.path("expiryDerived").asBoolean())previous.remove("expiresOn");if(previous.path("warrantyDerived").asBoolean())previous.remove("warrantyExpiresOn");}if(input.has("expiresOn"))previous.remove("expiryDerived");if(input.has("warrantyExpiresOn"))previous.remove("warrantyDerived");previous.setAll(input);ObjectNode b=validateBusiness(previous);s.db.update("UPDATE penny_sales SET business=?::jsonb,updated_at=now() WHERE id=?",b.toString(),lineId);String kind=b.path("operationalKind").asText();if(Set.of("SOFTWARE","HARDWARE").contains(kind)){s.require(auth,"PRODUCTS_WRITE");if(input.hasNonNull("serialNumber")&&s.db.queryForObject("SELECT count(*) FROM penny_installed_products WHERE sale_id=?",Integer.class,lineId)>1)throw M2Support.bad("Completa le matricole delle singole unità nel parco hardware");s.db.update("UPDATE penny_installed_products SET business=business||?::jsonb,license_key=CASE WHEN ? THEN ? ELSE license_key END,serial_number=CASE WHEN ? THEN ? ELSE serial_number END,installed_on=CASE WHEN ? THEN ? ELSE installed_on END,license_expires_on=CASE WHEN ? THEN ? ELSE license_expires_on END,warranty_until=CASE WHEN ? THEN ? ELSE warranty_until END,updated_at=now() WHERE sale_id=?",installedBusiness(b,kind).toString(),input.has("licenseId"),kind.equals("SOFTWARE")?text(b,"licenseId"):null,input.has("serialNumber"),kind.equals("HARDWARE")?text(b,"serialNumber"):null,input.has("effectiveFrom"),date(b,"effectiveFrom"),kind.equals("SOFTWARE")&&(input.has("effectiveFrom")||input.has("expiresOn")),date(b,"expiresOn"),input.has("effectiveFrom")||input.has("warrantyExpiresOn"),date(b,"warrantyExpiresOn"),lineId);}else if(Set.of("TRAINING","CONTRACT","DEVELOPMENT").contains(kind)){s.require(auth,it.penny.api.records.CustomerRecordService.permission(kind)+"_WRITE");if(kind.equals("CONTRACT")){for(var record:s.db.queryForList("SELECT id,starts_on,expires_on FROM penny_customer_records WHERE sale_id=? AND deleted_at IS NULL FOR UPDATE",lineId)){if(!Objects.equals(Objects.toString(record.get("starts_on"),null),Objects.toString(date(b,"effectiveFrom"),null))||!Objects.equals(Objects.toString(record.get("expires_on"),null),Objects.toString(date(b,"expiresOn"),null)))s.db.update("INSERT INTO penny_contract_renewals(record_id,previous_start,previous_end,new_start,new_end,reason,actor,event_type) VALUES (?,?,?,?,?,?,?,'CORRECTION')",record.get("id"),record.get("starts_on"),record.get("expires_on"),date(b,"effectiveFrom"),date(b,"expiresOn"),"Aggiornamento date dalla riga ordine",auth.getName());}}s.db.update("UPDATE penny_customer_records SET starts_on=?,expires_on=?,updated_at=now() WHERE sale_id=? AND deleted_at IS NULL",date(b,"effectiveFrom"),date(b,"expiresOn"),lineId);}s.audit(auth,"SALE_OPERATIONS_UPDATED","SALE",lineId,Map.of());return Map.of("updated",true);}
}
